-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "Fuoco"
L["rm.era.mage.fire.Description"] = "Fuoco dal livello 10 al 60, scelta quando hai punti in Fuoco e nessuno in Gelo, o quando Fuoco è il tuo albero principale. Apre con Pirosfera (altrimenti Palla di Fuoco); Pirosfera dopo Prontezza di Spirito; Bruciatura mantiene cinque cumuli di Vulnerabilità al Fuoco con Bruciatura Migliorata sui bersagli che sopravvivranno; Detonazione di Fuoco e Bruciatura per finire; Palla di Fuoco come riempitivo. Tre o più nemici ingaggiati: Ondata di Fuoco, Colonna di Fuoco, Esplosione Arcana, Cono di Freddo, Tormenta. Promemoria: Combustione a cinque cumuli di Bruciatura sulle élite e nei combattimenti lunghi, armatura, Intelletto Arcano, gemme di mana, Barriera di Ghiaccio, Scudo di Mana, Evocazione, Controincantesimo, Rimozione Maledizione Inferiore, Blocco di Ghiaccio, Prontezza di Spirito. Disattivato per impostazione predefinita: intercalare Detonazione di Fuoco ogni volta che è pronta."
L["rm.era.mage.fire.warcrafttavern.Name"] = "Fuoco (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Fuoco secondo Warcraft Tavern, un'alternativa alla rotazione integrata consigliata Fuoco, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Combustione viene usata all'ingaggio su élite e boss invece di aspettare i cumuli di Bruciatura; apre con Pirosfera; Bruciatura mantiene cinque cumuli con Bruciatura Migliorata; Palla di Fuoco come riempitivo; Detonazione di Fuoco solo in movimento. Gruppi di nemici: prima Colonna di Fuoco, poi Esplosione Arcana, Cono di Freddo e Ondata di Fuoco da vicino, Tormenta dalla distanza. Stessi promemoria della rotazione integrata Fuoco."
L["rm.era.mage.frost.Name"] = "Gelo"
L["rm.era.mage.frost.Description"] = "Gelo dal livello 1 al 60, anche per le build Arcano e la scelta predefinita del Mago prima dei talenti. Dardo di Gelo (Palla di Fuoco prima del livello 4); Esplosione Gelida quando un mostro ti raggiunge, tranne sui boss delle incursioni; Missili Arcani una volta che un mostro ti raggiunge se hai Missili Arcani Migliorati; Cono di Freddo, Esplosione Arcana e Tormenta quando sono ingaggiati tre o più nemici; Detonazione di Fuoco in movimento con mana in avanzo; Detonazione di Fuoco e la bacchetta finiscono i mostri comuni quando giochi da solo; bacchetta quando sei senza mana. Promemoria: armatura (Armatura di Ghiaccio da solo, Armatura Magica in gruppo, senza mai sostituire quella che hai scelto), Intelletto Arcano, evocazione e uso delle gemme di mana, Barriera di Ghiaccio, Scudo di Mana, Evocazione, Controincantesimo, Rimozione Maledizione Inferiore, Blocco di Ghiaccio, Prontezza Gelida, Potere Arcano e Prontezza di Spirito. Disattivati per impostazione predefinita: Colonna di Fuoco con Frantumazione e Dardo di Gelo di grado 1 per accumulare Gelo Invernale. Traslazione, Metamorfosi, kiting e scelta del bersaglio restano a te."
L["rm.era.mage.frost.icyveins.Name"] = "Gelo, grinding ad area (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Livellamento con Tormenta secondo la guida al grinding ad area di Icy Veins, scelta automaticamente quando giochi da solo con Tormenta Migliorata. Da due nemici ingaggiati: Esplosione Gelida sul gruppo, Cono di Freddo mentre Esplosione Gelida è in tempo di recupero, Tormenta quando nessuno ti è accanto, Esplosione Arcana quando lo sono; Dardo di Gelo su un singolo bersaglio, Detonazione di Fuoco e la bacchetta per finire. Scudo di Mana e Barriera di Ghiaccio vengono attivati prima di ogni ingaggio. Radunare il gruppo, Traslazione e kiting restano a te."
L["rm.forever.mage.arcane.Name"] = "Arcano"
L["rm.forever.mage.arcane.Description"] = "Arcano una volta che Arcano è il tuo albero dei talenti principale con 11 punti e conosci Detonazione Arcana. Ingaggia con Dardo di Gelo da solo o Detonazione Arcana in gruppo; poi Missili Arcani con Raffica di Missili, Detonazione Arcana con Lucidità, Ira Arcana a tre cumuli di Detonazione Arcana, Detonazione Arcana fino a quattro cumuli sulle élite e due sugli altri bersagli finché te lo puoi permettere (il mana è nascosto su Forever), poi Dardo di Gelofuoco, Dardo di Gelo o Palla di Fuoco per cercare Raffica di Missili, e una bacchetta quando giochi da solo e non puoi permetterti un incantesimo. Senza Ira Arcana (il design più vecchio della beta) Getto di Fuoco spende i cumuli. In movimento: Getto di Fuoco. Tre o più nemici che ti combattono: Esplosione Arcana. Promemoria: Presenza Mentale e Potere Arcano sulle élite (Potere Arcano non aspetta più metà del tuo mana), più i promemoria di mantenimento del Mago."
L["rm.forever.mage.fire.Name"] = "Fuoco"
L["rm.forever.mage.fire.Description"] = "Fuoco una volta che Fuoco è il tuo albero dei talenti principale con 11 punti (il livello di Pirosfera). Ingaggia con Pirosfera sulle élite, altrimenti Dardo di Gelofuoco o Palla di Fuoco; poi Pirosfera a tre cumuli di Riscaldamento, Lancia di Ghiaccio con Dita di Gelo o su un bersaglio congelato (ibridi Fuoco/Gelo), Getto di Fuoco appena pronto, Bruciatura per mantenere i tuoi cinque cumuli di Vulnerabilità al Fuoco sulle élite, Dardo di Gelofuoco (dal 40) o Palla di Fuoco, bacchetta quando giochi da solo e non puoi permetterti un incantesimo. In movimento: Getto di Fuoco o Lancia di Ghiaccio. Quattro o più nemici che ti combattono: Colonna di Fuoco, Onda d'Urto, Esplosione Arcana. Bruciatura avvia i cumuli solo quando hai Bruciatura Migliorata; una Bruciatura a distanza ravvicinata resta disattivata finché non la attivi. Promemoria: Combustione e Presenza Mentale sulle élite, più i promemoria di mantenimento del Mago."
L["rm.forever.mage.fire.icyveins.Name"] = "Fuoco da livellamento (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "La build Fuoco da livellamento di Icy Veins senza Bruciatura Migliorata, un'alternativa alla rotazione integrata consigliata Fuoco, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Ingaggia con Pirosfera, usa Getto di Fuoco per spendere Scia di Fuoco, Bruciatura mentre il mostro si avvicina (su Forever la salute del bersaglio è nascosta, quindi i colpi finali sui bersagli con poca salute spettano a te), poi Dardo di Gelofuoco (dal 40) o Palla di Fuoco. Stessa area d'effetto, movimento, bacchetta e promemoria della rotazione integrata Fuoco, senza Combustione e Presenza Mentale."
L["rm.forever.mage.frost.Name"] = "Gelo"
L["rm.forever.mage.frost.Description"] = "Gelo dal livello 1 al 60, e la scelta predefinita del Mago di Forever prima degli incantesimi da talento (Palla di Fuoco fino a Dardo di Gelo al livello 4). Ingaggia con Dardo di Gelo; poi Lancia di Ghiaccio con Dita di Gelo o su un bersaglio congelato (anche mentre Dardo di Gelo è ancora in lancio, per annullarlo o accodarla), Cono di Freddo a cinque cumuli di Gelo Invernale, Missili Arcani con Raffica di Missili, Dardo di Gelo, e una bacchetta quando giochi da solo e non puoi permetterti Dardo di Gelo. In movimento: Lancia di Ghiaccio, altrimenti Getto di Fuoco. Tre o più nemici che ti combattono: Cono di Freddo; cinque o più: Bufera di Neve, oppure Esplosione Arcana con un mostro addosso. L'area d'effetto con Colonna di Fuoco ed Esplosione Arcana di Warcraft Tavern è inclusa ma disattivata. Promemoria: Intelletto Arcano, armatura (di Ghiaccio o di Gelo da solo, Armatura del Mago in gruppo, senza mai sostituire quella che hai scelto), Barriera di Ghiaccio, Controincantesimo, Rimozione Maledizione Inferiore, Esplosione Gelida quando un mostro ti raggiunge, Ondata di Freddo. Su Forever salute e mana sono nascosti agli addon, quindi finire i bersagli con poca salute con Getto di Fuoco, Evocazione e Blocco di Ghiaccio sono una tua scelta; anche Traslazione, kiting, Metamorfosi e gemme del mana restano a te."
L["rm.mop.mage.arcane.Name"] = "Consigliata"
L["rm.mop.mage.arcane.Description"] = "Consigliata per Arcano, dal livello 10 al 90 (selezionata nella specializzazione Arcano). Detonazione Arcana accumula quattro cariche arcane; con quattro, un proc di Missili Arcani! viene speso con Missili, e senza proc Sbarramento Arcano parte una volta che il tuo mana scende sotto il 90%. Sopra il 95% di mana continua con Detonazione, che è come la gioca il simulatore. Missili non viene mai lasciato fermo su due proc, Sbarramento viene lanciato prima che Alterazione Temporale ti riporti indietro, e con due o più nemici Sbarramento parte ogni quattro cariche; Cono di Freddo ed Esplosione Arcana quando cinque nemici sono vicini. Mantiene attiva la tua bomba da talento, e Detonazione di Fuoco o Lancia di Ghiaccio in movimento senza Cuore di Ghiaccio. Promemoria: Potere Arcano e Alterazione Temporale a quattro cariche con un proc, Armatura Gelida (Lavica prima del livello 54), Acume Arcano, Controincantesimo, Gemma di Mana, Immagine Speculare, Barriera di Ghiaccio, Cuore di Ghiaccio, Runa del Potere o Invocazione. Distorsione Temporale, Ruba Incantesimo e Prontezza di Spirito sono disattivati; Runa del Potere va comunque posizionata a mano."
L["rm.mop.mage.arcane.icyveins.Name"] = "Sbarramento a quattro cariche (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "La regola Arcano delle guide (Icy Veins, Wowhead, Method, wowtbc.gg), un'alternativa alla rotazione integrata Arcano consigliata: a quattro cariche arcane, Missili Arcani se c'è un proc attivo, altrimenti Sbarramento Arcano, qualunque sia il tuo mana; Missili solo a quattro cariche. Tutto il resto (Alterazione Temporale, bombe, effetti ad area, movimento, promemoria) è uguale a quella consigliata, tranne che Potere Arcano viene suggerito a quattro cariche senza aspettare un proc. Disattivata per impostazione predefinita: attivala e disattiva la rotazione integrata Arcano consigliata, oppure alzane la priorità."
L["rm.mop.mage.fire.Name"] = "Consigliata"
L["rm.mop.mage.fire.Description"] = "Consigliata per Fuoco, dal livello 10 al 90 (selezionata nella specializzazione Fuoco). Apre con una Pirosfera lanciata normalmente, poi Detonazione Infernale (Detonazione di Fuoco prima del livello 24) trasforma Riscaldamento in un proc di Pirosfera!, che viene lanciata subito a meno che Combustione non stia per tornare disponibile; poi aspetta il Riscaldamento successivo mentre lanci Palla di Fuoco. Combustione si accende subito dopo una Pirosfera mentre Incendio e il danno periodico di Pirosfera sono sul bersaglio; l'addon non può vedere quanto è grande Incendio, quindi giudica tu se è debole. Mantiene attiva la tua bomba da talento, la diffonde con Detonazione Infernale quando due o più nemici ti combattono, Cono di Freddo ed Esplosione Arcana per cinque nemici vicini, Bruciatura in movimento. Promemoria: Armatura Lavica, Prontezza di Spirito, Alterazione Temporale con entrambi i proc, Gemma di Mana, Acume Arcano, Controincantesimo, Immagine Speculare, Barriera di Ghiaccio, Cuore di Ghiaccio, Invocazione o Runa del Potere. Soffio del Drago, Distorsione Temporale e Ruba Incantesimo sono disattivati."
L["rm.mop.mage.fire.icyveins.Name"] = "Trattieni Pirosfera! (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "Il gioco Fuoco di Icy Veins, Method e wowtbc.gg, un'alternativa alla rotazione integrata Fuoco consigliata: un proc di Pirosfera! viene trattenuto finché non gli si aggiunge un Riscaldamento, poi viene lanciato insieme alla tua Palla di Fuoco, e speso da solo soltanto quando sta per scadere. Tutto il resto è uguale a quella consigliata. Disattivata per impostazione predefinita: attivala e disattiva la rotazione integrata Fuoco consigliata, oppure alzane la priorità."
L["rm.mop.mage.frost.Name"] = "Consigliata"
L["rm.mop.mage.frost.Description"] = "Gelo dal livello 10 al 90 (selezionata nella specializzazione Gelo). Lancia di Ghiaccio a due cumuli di Dita di Gelo, Palla di Fuocogelo con Mente Fredda, la tua bomba da talento, Globo Congelato, Lancia di Ghiaccio con un cumulo di Dita di Gelo, Dardo di Gelo; dal livello 87 un proc viene trattenuto per Alterazione Temporale quando mancano meno di 10 secondi. Con due o più nemici: Globo Congelato, Cono di Freddo ed Esplosione Arcana quando sono vicini, Tormenta quando quattro stanno fermi. Lancia di Ghiaccio e Detonazione di Fuoco in movimento senza Cuore di Ghiaccio. Promemoria: Elementale dell'Acqua, Congelamento su tutto tranne un boss (posizionalo tu), Vene Gelide sincronizzato con Alterazione Temporale, Alterazione Temporale a due cumuli di Dita di Gelo durante Vene Gelide, Armatura Gelida (Lavica prima del livello 54), Gemma di Mana, Acume Arcano, Controincantesimo, Immagine Speculare, Barriera di Ghiaccio, Cuore di Ghiaccio, Invocazione o Runa del Potere. Prontezza Gelida, Prontezza di Spirito, Distorsione Temporale e Ruba Incantesimo sono disattivati."
L["rm.mop.mage.unspecialized.Name"] = "Prima di una specializzazione"
L["rm.mop.mage.unspecialized.Description"] = "Per i livelli da 1 a 9, e qualsiasi Mago che non ha ancora scelto una specializzazione. Palla di Fuocogelo, Detonazione di Fuoco per finire un bersaglio o in movimento, Lancia di Ghiaccio in movimento una volta appresa, Esplosione Arcana quando tre o più nemici sono a portata di mischia. Promemoria: Esplosione Gelida quando un mostro ti raggiunge, Controincantesimo, e Armatura Lavica e Acume Arcano se ci arrivi. Scegliere una specializzazione al livello 10 passa alla rotazione integrata di quella specializzazione."
L["rm.retail.mage.arcane.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.mage.arcane.Description"] = "Consigliata per Arcano. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Eruzione Arcana in combattimento, Intelletto Arcano fuori combattimento, Controincantesimo su un lancio interrompibile, Barriera Prismatica ogni volta che è pronta in combattimento e il tuo tempo di recupero razziale in combattimento. I lanci nemici sono nascosti in combattimento, quindi Controincantesimo si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi Blocco di Ghiaccio e gli altri pulsanti d'emergenza sono una tua scelta. Immagine Speculare, Alterazione Temporale, Traslazione e i monili restano a te."
L["rm.retail.mage.arcane.guide.Name"] = "Riferimento (Icy Veins e SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Arcano delle guide. Salva Arcana e Lancio Istintivo sono nascosti agli addon in combattimento in Midnight (restano visibili solo le cariche arcane), quindi lì non può funzionare; il mana è nascosto su Retail, quindi Evocazione a mana basso spetta a te; leggila o duplicala per sperimentare. Ingaggia con Detonazione Arcana. Furia del Sole: Missili Arcani con Lancio Istintivo sotto 12 cumuli di Salva, Dardo Prismatico fuori da Anima Arcana, Sbarramento Arcano a quattro cariche con 12 cumuli di Salva e Lancio Istintivo o con 25 cumuli di Salva, oppure con Anima Arcana a qualsiasi numero di cariche, Dardo Prismatico, Globo Arcano sotto tre cariche, Impulso Arcano contro tre nemici o a zero cariche, Detonazione Arcana. Scagliamagie (se conosci Magia Scheggiante): Dardo Prismatico, Globo sui gruppi di nemici, Sbarramento a 20 cumuli di Salva (solo a quattro cariche contro due o più nemici), Missili con Lancio Istintivo sotto 15 cumuli di Salva, Globo e Impulso sotto tre cariche (niente Impulso durante Eruzione Arcana), Detonazione Arcana. Sbarramento Arcano quando Detonazione non può essere lanciata. Promemoria: Eruzione Arcana, Tocco del Magus dopo uno Sbarramento o un Dardo Prismatico durante Eruzione o con largo anticipo su di essa, Prontezza di Spirito a zero cariche dopo uno Sbarramento, più i promemoria della rotazione integrata dell'Assistente di Combattimento."
L["rm.retail.mage.fire.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.mage.fire.Description"] = "Consigliata per Fuoco. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Combustione in combattimento, Intelletto Arcano fuori combattimento, Controincantesimo su un lancio interrompibile, Barriera Fiammeggiante ogni volta che è pronta in combattimento e il tuo tempo di recupero razziale in combattimento. I lanci nemici sono nascosti in combattimento, quindi Controincantesimo si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi Blocco di Ghiaccio e gli altri pulsanti d'emergenza sono una tua scelta."
L["rm.retail.mage.fire.guide.Name"] = "Riferimento (Icy Veins, Wowhead e SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Fuoco delle guide. Serie Bollente, Riscaldamento, Piroclasma e le cariche di Detonazione di Fuoco sono nascosti in combattimento in Midnight, quindi lì non può funzionare. Detonazione di Fuoco mentre un lancio sta finendo per trasformare Riscaldamento in Serie Bollente; ingaggia con Pirosfera. Pirosfera (Colonna di Fuoco contro quattro o più nemici) con Ipertermia, Meteora, Pirosfera con Serie Bollente, Detonazione di Fuoco con Riscaldamento durante Combustione, Pirosfera con Piroclasma, Bruciatura con Riverbero di Calore o in movimento, Detonazione di Fuoco con Riscaldamento, poi Palla di Fuocogelo o Palla di Fuoco. Promemoria: Combustione mentre termina un lancio non istantaneo, Barriera Fiammeggiante e i promemoria di utilità. Attendere Inferno di Fuoco e far coincidere Meteora con Combustione restano a te."
L["rm.retail.mage.frost.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.mage.frost.Description"] = "Consigliata per Gelo. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Evocazione: Elementale dell'Acqua quando hai il talento e nessun elementale, Intelletto Arcano fuori combattimento, Controincantesimo su un lancio interrompibile, Barriera di Ghiaccio ogni volta che è pronta in combattimento e il tuo tempo di recupero razziale in combattimento. I lanci nemici sono nascosti in combattimento, quindi Controincantesimo si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi Blocco di Ghiaccio e gli altri pulsanti d'emergenza sono una tua scelta."
L["rm.retail.mage.frost.guide.Name"] = "Riferimento (Icy Veins e SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Gelo delle guide per ogni albero eroico. Proc, cumuli di Congelamento e tempi di recupero sono nascosti in combattimento in Midnight, quindi lì non può funzionare. Ingaggia con Palla di Fuocogelo o Dardo di Gelo. Fuocogelo (se conosci Palla di Fuocogelo): Aculeo Glaciale quando è pronto, Tempesta di Comete contro uno o due nemici, Raffica di Colpi con Mente Fredda senza Vuoto Termico, Lancia di Ghiaccio con due cumuli di Dita di Gelo, Raggio di Gelo, Globo Congelato, Tormenta con Pioggia Congelante contro tre nemici, Lancia di Ghiaccio con Dita di Gelo e Vuoto Termico o a dodici cumuli di Congelamento, Raffica di Colpi, Esplosione di Ghiaccio o Cono di Freddo contro cinque, poi Aculeo Glaciale o Palla di Fuocogelo. Scagliamagie: Tempesta di Comete, Raffica di Colpi con Mente Fredda, Lancia di Ghiaccio con due cumuli di Dita, Globo Congelato, Aculeo Glaciale quando è pronto, Tormenta con Pioggia Congelante, Lancia di Ghiaccio con Dita di Gelo o sei cumuli di Congelamento, Raggio di Gelo, Raffica di Colpi, Esplosione di Ghiaccio o Cono di Freddo contro quattro, Tormenta contro sette, poi Aculeo Glaciale o Dardo di Gelo. Lancia di Ghiaccio in movimento. Promemoria: Evocazione: Elementale dell'Acqua, Barriera di Ghiaccio e i promemoria di utilità."
L["rm.retail.mage.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.mage.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Mago). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Mago condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.sod.mage.arcane.Name"] = "Arcano (SoD)"
L["rm.sod.mage.arcane.Description"] = "Danni Arcano della Season of Discovery, scelta quando Arcano è il tuo albero principale e Detonazione Arcana è incisa. Missili Arcani con Raffica di Missili; Sbarramento Arcano a quattro cumuli di Detonazione Arcana; Dardo di Fuoco Funesto quando è sicuro, mai a quattro o più cumuli di Fuoco Funesto; Fiamma Vivente appena pronta; Detonazione Arcana come riempitivo. Sbarramento Arcano e Detonazione di Fuoco in movimento; Fiamma Vivente ed Esplosione Arcana sui gruppi di nemici. Promemoria: Potere Arcano sulle élite e nei combattimenti lunghi, Prontezza di Spirito con Potere Arcano o in movimento, Vene Gelide, Prontezza Gelida e gli altri promemoria del Mago."
L["rm.sod.mage.fire.Name"] = "Fuoco (SoD)"
L["rm.sod.mage.fire.Description"] = "Fuoco della Season of Discovery dal livello 1 al 60, e lì la scelta predefinita del Mago. Usa le rune che hai inciso: Pirosfera subito con Serie Bollente; Bomba Vivente mantenuta sui bersagli che sopravvivranno; Bruciatura con Bruciatura Migliorata mentre Vulnerabilità al Fuoco è sotto due cumuli o sta per svanire; Fiamma Vivente appena pronta; Dardo di Fuoco Funesto a cinque cumuli di Vulnerabilità al Fuoco, mai a quattro o più cumuli di Fuoco Funesto (il quinto ti uccide); Palla di Fuocogelo, altrimenti Palla di Fuoco. Bomba Vivente, Fiamma Vivente e Detonazione di Fuoco in movimento; Fiamma Vivente, Bomba Vivente, Ondata di Fuoco, Cono di Freddo, Colonna di Fuoco e Tormenta sui gruppi di nemici. Promemoria: Detonazione di Fuoco con Surriscaldamento, Combustione, Vene Gelide e Prontezza Gelida, Armatura Lavica o un'altra armatura, Intelletto Arcano, gemme di mana, Barriera di Ghiaccio, Scudo di Mana, Evocazione, Controincantesimo, rimozione delle maledizioni, Blocco di Ghiaccio. Diffondere Bomba Vivente su più bersagli resta a te."
L["rm.sod.mage.frost.Name"] = "Gelo (SoD)"
L["rm.sod.mage.frost.Description"] = "Gelo della Season of Discovery dal livello 10, scelta quando Gelo è il tuo albero principale. Dita di Gelo va in Lancia di Ghiaccio a tre o più dei tuoi cumuli di Glaciazione, altrimenti in Gelo Profondo; Dardo di Fuoco Funesto con un proc di Mente Fredda e altrimenti quando è sicuro, mai a quattro o più cumuli di Fuoco Funesto; Bomba Vivente e Fiamma Vivente quando sono incise; Dardo di Geloincanto, altrimenti Palla di Fuocogelo, altrimenti Dardo di Gelo. Lancia di Ghiaccio, Globo Congelato, Bomba Vivente e Detonazione di Fuoco in movimento; Globo Congelato, Fiamma Vivente, Bomba Vivente, Tormenta e Cono di Freddo sui gruppi di nemici. Promemoria: Globo Congelato, Vene Gelide, Prontezza Gelida, armatura, gemme di mana e gli altri promemoria del Mago. Mettere in coda un incantesimo mentre arriva un dardo resta a te."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "Gelo, rune di Fuoco (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "La build Gelo della Fase 4 di Warcraft Tavern con rune di Fuoco, un'alternativa alla rotazione integrata consigliata Gelo della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Apre con Pirosfera; Pirosfera con Serie Bollente; Bomba Vivente sempre attiva; Bruciatura fino a cinque cumuli con Bruciatura Migliorata; Dardo di Fuoco Funesto solo con un proc di Mente Fredda e mai a quattro o più cumuli di Fuoco Funesto; Palla di Fuocogelo come riempitivo. Bomba Vivente e Detonazione di Fuoco in movimento; Bomba Vivente, Cono di Freddo e Tormenta sui gruppi di nemici. Promemoria: Detonazione di Fuoco con Surriscaldamento, Globo Congelato durante Vene Gelide, Vene Gelide, Prontezza Gelida e gli altri promemoria del Mago."
L["rm.sod.mage.healer.Name"] = "Guaritore (SoD)"
L["rm.sod.mage.healer.Description"] = "Cure del Mago della Season of Discovery, scelta quando Rigenerazione o Rigenerazione di Massa è incisa. Con un bersaglio amico: Riavvolgimento Temporale e Preservazione Cronostatica sotto metà della salute, Rigenerazione quando manca il tuo Faro Temporale, Rigenerazione di Massa, Anomalia Temporale. Con un bersaglio nemico, danni che curano i tuoi fari: Dardo di Geloincanto per i guaritori Gelo, altrimenti Missili Arcani con Raffica di Missili, Sbarramento Arcano a due cumuli di Detonazione Arcana, Dardo di Fuoco Funesto quando è sicuro (mai a quattro o più cumuli di Fuoco Funesto) e Detonazione Arcana. Promemoria: Potere Arcano, Prontezza di Spirito, Globo Congelato e gli altri promemoria del Mago. Disattivati per impostazione predefinita: Esplosione Arcana sui gruppi di nemici, e Lancia di Ghiaccio e Gelo Profondo per i guaritori Gelo. Mentre incanali Rigenerazione di Massa viene già mostrato l'incantesimo successivo, così puoi annullarla subito (la sua cura diretta è piccola). La scelta di chi curare resta a te."
L["rm.tbc.mage.arcane.Name"] = "Arcano"
L["rm.tbc.mage.arcane.Description"] = "Arcano, scelto quando Arcano è il tuo albero dei talenti principale. Prima del livello 64: Missili Arcani, con Dardo di Gelo quando il mana scarseggia. Dal 64: Detonazione Arcana durante la fase di consumo (Potere Arcano, Brama di Sangue o mana sopra il 35%), altrimenti tre cumuli di Detonazione Arcana e Dardo di Gelo finché stanno per scadere. Esplosione Arcana e Cono di Freddo contro tre o più nemici. I promemoria includono Potere Arcano, Presenza Mentale, gemma del mana ed Evocazione."
L["rm.tbc.mage.fire.icyveins.Name"] = "Fuoco (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Fuoco secondo Icy Veins, scelto quando Fuoco è il tuo albero dei talenti principale. Pirosfera apre l'ingaggio una volta appresa, Bruciatura Migliorata mantiene cinque cumuli di Vulnerabilità al Fuoco, Palla di Fuoco fa da riempitivo, Getto di Fuoco è per il movimento; Onda d'Urto, Soffio del Drago e Colonna di Fuoco contro tre o più nemici. Promemoria: Armatura Fusa, Armatura del Mago o Armatura di Ghiaccio, Combustione sotto il 20% di salute del bersaglio, gemma del mana, Evocazione e le utilità comuni del Mago."
L["rm.tbc.mage.fire.wowhead.Name"] = "Fuoco (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "Fuoco secondo Wowhead e simulatore. Come la rotazione integrata Fuoco di Icy Veins, ma intercala Getto di Fuoco ogni volta che è pronto mentre sei fermo (più danni, più mana) e apre con Palla di Fuoco invece di Pirosfera. Un'alternativa alla rotazione integrata consigliata Fuoco di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.tbc.mage.frost.Name"] = "Gelo"
L["rm.tbc.mage.frost.Description"] = "Gelo dal livello 1 al 70, e la scelta predefinita del Mago prima dei talenti. Dardo di Gelo (Palla di Fuoco prima del livello 4), Esplosione Gelida quando qualcosa ti colpisce, Cono di Freddo con Bufera di Neve o Esplosione Arcana quando sei impegnato con tre o più nemici, Lancia di Ghiaccio sui bersagli congelati e in movimento, bacchetta quando hai finito il mana. Promemoria: armatura, Intelletto Arcano, gemma del mana, Evocazione, Controincantesimo, Ruba Incantesimo, Barriera di Ghiaccio, Vene Gelide, Ondata di Freddo ed Elementale dell'Acqua. Traslazione, Blocco di Ghiaccio, kiting e scelta del bersaglio restano a te."
